import { Box } from '@mui/material';
import React, { useEffect, useRef, useState } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import type { PDFDocumentProxy } from 'pdfjs-dist';

// Served as-is from public/ (copied on postinstall); bundling it lets Babel inject require() calls that break the worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.min.js`;

interface IPdfCanvasViewerProps {
  blob: Blob;
}

// Renders PDF pages onto plain canvases so the preview has no browser viewer chrome
const PdfCanvasViewer = ({ blob }: IPdfCanvasViewerProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [pdf, setPdf] = useState<PDFDocumentProxy | null>(null);
  const [width, setWidth] = useState(0);

  useEffect(() => {
    let cancelled = false;
    let doc: PDFDocumentProxy | null = null;
    blob.arrayBuffer().then((buffer) =>
      pdfjsLib.getDocument({ data: buffer }).promise.then((loaded) => {
        doc = loaded;
        if (cancelled) loaded.destroy();
        else setPdf(loaded);
      })
    );
    return () => {
      cancelled = true;
      doc?.destroy();
    };
  }, [blob]);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => setWidth(Math.floor(entry.contentRect.width)));
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const el = containerRef.current;
    if (!pdf || !el || !width) return;
    let cancelled = false;

    const render = async () => {
      const canvases: HTMLCanvasElement[] = [];
      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        if (cancelled) return;
        const baseViewport = page.getViewport({ scale: 1 });
        const scale = width / baseViewport.width;
        const ratio = window.devicePixelRatio || 1;
        const viewport = page.getViewport({ scale: scale * ratio });

        const canvas = document.createElement('canvas');
        canvas.width = viewport.width;
        canvas.height = viewport.height;
        canvas.style.width = `${width}px`;
        canvas.style.height = `${viewport.height / ratio}px`;
        canvas.style.display = 'block';
        canvas.style.backgroundColor = '#fff';
        canvas.style.boxShadow = '0 4px 20px rgba(15,29,77,0.10)';
        canvas.style.borderRadius = '4px';

        await page.render({ canvasContext: canvas.getContext('2d')!, viewport }).promise;
        if (cancelled) return;
        canvases.push(canvas);
      }
      el.replaceChildren(...canvases);
    };

    render();
    return () => {
      cancelled = true;
    };
  }, [pdf, width]);

  return <Box ref={containerRef} sx={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 2 }} />;
};

export default PdfCanvasViewer;
